import{_ as i,c as s,o as a,aj as t}from"./chunks/framework.BlveriQe.js";const k=JSON.parse('{"title":"JsBaoNetworkError","description":"","frontmatter":{},"headers":[],"relativePath":"reference/swift-client/JsBaoNetworkError.md","filePath":"reference/swift-client/JsBaoNetworkError.md"}'),r={name:"reference/swift-client/JsBaoNetworkError.md"};function o(n,e,h,l,d,c){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="jsbaonetworkerror" tabindex="-1"><code>JsBaoNetworkError</code> <a class="header-anchor" href="#jsbaonetworkerror" aria-label="Permalink to “JsBaoNetworkError”">​</a></h1><p><code>struct</code> — swift-client/Sources/JsBaoClient/Types/Errors.swift</p><p>A transport or token-refresh failure: the request could not be completed against the server. Parity with the JS client&#39;s <code>JsBaoNetworkError</code> (<code>src/client/errors.ts</code>).</p><p><strong>This does not mean the request never reached the server.</strong> The client raises it whenever the HTTP layer could not produce a usable response — DNS/TLS/connection failures, timeouts, and (via <code>AuthController</code>) any refresh failure other than an HTTP 401/403, which includes 5xx responses and decode failures. Treat it as <em>retryable</em>, not as proof of no side effect.</p><p>These used to surface as the raw <code>URLError</code> <code>URLSession</code> produced, so apps had to catch a Foundation type to handle them. They are now normalized through one internal helper, so <code>URLError</code> no longer escapes the client&#39;s HTTP paths.</p><p>A cancelled request is <strong>not</strong> reported here: <code>URLError.cancelled</code> is normalized to <code>CancellationError</code>, matching how the client already reports cancellation elsewhere.</p><h2 id="message" tabindex="-1"><code>message</code> <a class="header-anchor" href="#message" aria-label="Permalink to “message”">​</a></h2><div class="language-swift"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> message: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span></span></code></pre></div><p>The underlying failure&#39;s <code>localizedDescription</code>, verbatim — except on the refresh path, where a non-<code>LocalizedError</code> <code>HttpError</code> is spelled out as <code>&quot;Token refresh failed: HTTP &lt;status&gt; …&quot;</code> (see <code>init(refreshFailure:)</code>).</p><h2 id="urlerrorcode" tabindex="-1"><code>urlErrorCode</code> <a class="header-anchor" href="#urlerrorcode" aria-label="Permalink to “urlErrorCode”">​</a></h2><div class="language-swift"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> urlErrorCode: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Int</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span></span></code></pre></div><p>The <code>URLError.Code</code> raw value when the failure came from <code>URLSession</code>, <code>nil</code> otherwise.</p><h2 id="init" tabindex="-1"><code>init</code> <a class="header-anchor" href="#init" aria-label="Permalink to “init”">​</a></h2><div class="language-swift"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">urlErrorCode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Int</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="istimeout" tabindex="-1"><code>isTimeout</code> <a class="header-anchor" href="#istimeout" aria-label="Permalink to “isTimeout”">​</a></h2><div class="language-swift"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> isTimeout: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Bool</span></span></code></pre></div><p>Whether the failure was a timeout. Computed from <code>urlErrorCode</code> rather than stored, so it cannot contradict it.</p><h2 id="errordescription" tabindex="-1"><code>errorDescription</code> <a class="header-anchor" href="#errordescription" aria-label="Permalink to “errorDescription”">​</a></h2><div class="language-swift"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> errorDescription: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { message }</span></span></code></pre></div><p>The underlying message verbatim — the client does not prefix it.</p>',20)])])}const g=i(r,[["render",o]]);export{k as __pageData,g as default};
